(1537757, 202186, 39336, '<td valign="top">a 10. I love the colors and the blurred background the "still" motion the look of pain? on the guys face as he''s hitting the ball with his head.</td>', 'a 10. I love the colors and the blurred background the "still" motion the look of pain? on the guys face as he''s hitting the ball with his head.', '2005-07-15 14:47:30.000000', NULL, 1),
(1537760, 201807, 39336, '<td valign="top">I think the whites are too bright.</td>', 'I think the whites are too bright.', '2005-07-15 14:47:58.000000', NULL, 1),
(1537763, 202172, 39336, '<td valign="top">I personally like the crop on this. Hope he/she was ok after the roll!</td>', 'I personally like the crop on this. Hope he/she was ok after the roll!', '2005-07-15 14:48:56.000000', NULL, 1),
(1537767, 202189, 39336, '<td valign="top">Nice crop! I love how you caught not one, not two, but THREE of the darts!</td>', 'Nice crop! I love how you caught not one, not two, but THREE of the darts!', '2005-07-15 14:49:28.000000', NULL, 1),
(1537770, 203152, 39336, '<td valign="top">ohhh that''s gotta hurt!</td>', 'ohhh that''s gotta hurt!', '2005-07-15 14:49:47.000000', NULL, 1),
(1537773, 202046, 39336, '<td valign="top">That''s such a sweet photo.</td>', 'That''s such a sweet photo.', '2005-07-15 14:50:07.000000', NULL, 1),
