(1537780, 201954, 39336, '<td valign="top">Wait, I saw another shot on here with basically the same shot? Or at least the same uniforms.</td>', 'Wait, I saw another shot on here with basically the same shot? Or at least the same uniforms.', '2005-07-15 14:51:41.000000', NULL, 1),
(1537781, 202993, 39336, '<td valign="top">Burn baby Burn!</td>', 'Burn baby Burn!', '2005-07-15 14:52:02.000000', NULL, 1),
