(1543979, 202228, 13547, '<td valign="top">I think you''ll find a lot of comments saying this is too blurred!  Good use of B&amp;W and also the rule of thirds!  Nice one mate (Clumpy rules!)</td>', 'I think you''ll find a lot of comments saying this is too blurred!  Good use of B&W and also the rule of thirds!  Nice one mate (Clumpy rules!)', '2005-07-18 14:08:20.000000', NULL, 1),
(1543980, 203269, 38921, '<td valign="top">Nice shot, I would have preferred a shallower DOF to isolate the subject better from the busy background - 7</td>', 'Nice shot, I would have preferred a shallower DOF to isolate the subject better from the busy background - 7', '2005-07-18 14:10:14.000000', NULL, 1),
(1543981, 201763, 35135, '<td valign="top">The subjects are too dark.  Open up the aperature.  It will reduce your depth of field, but we don''t need to see those other people anyway.</td>', 'The subjects are too dark.  Open up the aperature.  It will reduce your depth of field, but we don''t need to see those other people anyway.', '2005-07-18 14:10:16.000000', NULL, 1),
(1543982, 202694, 13547, '<td valign="top">I really like this idea, but the people don''t stand out all that well from the background, little bit hard to make them out.  Otherwise excellent, 8</td>', 'I really like this idea, but the people don''t stand out all that well from the background, little bit hard to make them out.  Otherwise excellent, 8', '2005-07-18 14:10:37.000000', NULL, 1),
(1543984, 203119, 13547, '<td valign="top">Fantastic capture!  Was it a good hit?  Hehe another title for this could be ''Good Shot'' - works 2 ways!</td>', 'Fantastic capture!  Was it a good hit?  Hehe another title for this could be ''Good Shot'' - works 2 ways!', '2005-07-18 14:11:46.000000', NULL, 1),
(1543985, 202365, 35135, '<td valign="top">Great shot.  Impression of a close race with BIG air.</td>', 'Great shot.  Impression of a close race with BIG air.', '2005-07-18 14:11:53.000000', NULL, 1),
(1543987, 203181, 39976, '<td valign="top">Cute dog</td>', 'Cute dog', '2005-07-18 14:12:05.000000', NULL, 1),
(1543989, 202788, 39976, '<td valign="top">Interesting shadows</td>', 'Interesting shadows', '2005-07-18 14:13:37.000000', NULL, 1),
(1543990, 202897, 13547, '<td valign="top">Good capture, but way too dark, you can hardly see her!</td>', 'Good capture, but way too dark, you can hardly see her!', '2005-07-18 14:13:42.000000', NULL, 1),
(1543995, 201466, 39976, '<td valign="top">Neat!</td>', 'Neat!', '2005-07-18 14:15:24.000000', NULL, 1),
